    </div>
    <div class="overlay hidden" id="gameoverOverlay">
      <div class="title">游戏结束</div>
      <div class="sub" id="finalScore">得分: 0</div>
      <button id="restartBtn">重新开始</button>
    </div>
  </div>
  <div class="sidebar">
    <div class="panel"><h3>下一方块</h3><canvas class="preview-canvas" id="previewCanvas"></canvas></div>
    <div class="panel"><h3>分数</h3><div class="val" id="scoreVal">0</div></div>
    <div class="panel"><h3>等级</h3><div class="val" id="levelVal">1</div></div>
    <div class="panel"><h3>行数</h3><div class="val" id="linesVal">0</div></div>
  </div>
</div>
<div class="controls" id="touchControls">
  <button class="ctrl-rotate" id="btnRotate">↻</button>
  <button class="ctrl-drop" id="btnDrop">⏬</button>
  <button class="ctrl-left" id="btnLeft">◀</button>
  <button class="ctrl-down" id="btnDown">▼</button>
  <button class="ctrl-right" id="btnRight">▶</button>
