  }
}

function spawnNext(){
  current=next||spawnPiece(randomPiece());
  next=spawnPiece(randomPiece());
  lastDropTime=performance.now();
  if(collides(current))triggerGameOver();
  drawPreview();
}

function triggerGameOver(){
  gameOver=true;paused=true;
  document.getElementById('finalScore').textContent='得分: '+score;
  document.getElementById('gameoverOverlay').classList.remove('hidden');
}

function movePiece(dx,dy){
  if(gameOver||paused)return false;
  if(!collides(current,dx,dy)){
    current.x+=dx;current.y+=dy;return true;
  }
  if(dy>0)lockPiece();
  return false;
}

function rotatePiece(){
  if(gameOver||paused)return;
  if(current.name==='O')return;
  const s=current.shape,n=s.length;
  const rotated=Array.from({length:n},()=>Array(n).fill(0));
  for(let r=0;r<n;r++)for(let c=0;c<n;c++)rotated[r][c]=s[n-1-c][r];
  const saved=current.shape;
  current.shape=rotated;
  const kicks=[0,-1,1,-2,2];
  let ok=false;
  for(const k of kicks){if(!collides(current,k,0)){current.x+=k;ok=true;break}}
  if(!ok)current.shape=saved;
}

function hardDrop(){
  if(gameOver||paused)return;
  while(!collides(current,0,1))current.y++;
  lockPiece();
  lastDropTime=performance.now();
}

// ─── 渲染 ──────────────────────────────
function draw(){
  ctx.fillStyle='#0a0a1a';ctx.fillRect(0,0,canvas.width,canvas.height);
  ctx.strokeStyle='#1a1a2e';ctx.lineWidth=.5;
  for(let r=0;r<=ROWS;r++){ctx.beginPath();ctx.moveTo(0,r*CELL);ctx.lineTo(COLS*CELL,r*CELL);ctx.stroke()}
  for(let c=0;c<=COLS;c++){ctx.beginPath();ctx.moveTo(c*CELL,0);ctx.lineTo(c*CELL,ROWS*CELL);ctx.stroke()}
  for(let r=0;r<ROWS;r++)for(let c=0;c<COLS;c++)
    if(board[r][c])drawCell(ctx,c,r,board[r][c]);
  // ghost piece
  if(current&&!gameOver){
    let gy=current.y;
    while(!collides(current,0,gy-current.y+1))gy++;
    if(gy!==current.y){
      const{shape,x,color}=current;
      for(let r=0;r<shape.length;r++)for(let c=0;c<shape[r].length;c++)
        if(shape[r][c])drawCell(ctx,c+x,r+gy,color,.25);
    }
  }
  // current piece
  if(current&&!gameOver){
    const{shape,x,color}=current;
    for(let r=0;r<shape.length;r++)for(let c=0;c<shape[r].length;c++)
      if(shape[r][c])drawCell(ctx,c+x,r+current.y,color,1);
  }
}

function drawCell(ctx,cx,cy,color,alpha=1){
  const x=cx*CELL,y=cy*CELL;
  ctx.globalAlpha=alpha;
  ctx.fillStyle=color;ctx.fillRect(x+1,y+1,CELL-2,CELL-2);
  ctx.fillStyle='rgba(255,255,255,.2)';ctx.fillRect(x+1,y+1,CELL-2,3);ctx.fillRect(x+1,y+1,3,CELL-2);
  ctx.fillStyle='rgba(0,0,0,.3)';ctx.fillRect(x+1,y+CELL-4,CELL-2,3);ctx.fillRect(x+CELL-4,y+1,3,CELL-2);
  ctx.globalAlpha=1;
}

function drawPreview(){
  pctx.clearRect(0,0,previewCanvas.width,previewCanvas.height);
  if(!next)return;
  const{shape,color}=next;
  const offX=Math.floor((4-shape[0].length)/2);
  const offY=Math.floor((4-shape.length)/2);
  for(let r=0;r<shape.length;r++)for(let c=0;c<shape[r].length;c++)
    if(shape[r][c])drawCell(pctx,c+offX,r+offY,color,1);
}

function updateUI(){
  document.getElementById('scoreVal').textContent=score;
  document.getElementById('levelVal').textContent=level;
  document.getElementById('linesVal').textContent=lines;
}

// ─── 游戏循环 ──────────────────────────
function gameLoop(now){
  if(!gameOver&&!paused){
    if(now-lastDropTime>=dropInterval){
      movePiece(0,1);
      lastDropTime=now;
    }
    draw();
  }
  animId=requestAnimationFrame(gameLoop);
}

// ─── 键盘输入 ──────────────────────────
document.addEventListener('keydown',e=>{
  if(e.key==='p'||e.key==='P'){
    if(gameOver)return;
    paused=!paused;
    if(paused)document.getElementById('pauseOverlay').classList.remove('hidden');
    else{document.getElementById('pauseOverlay').classList.add('hidden');lastDropTime=performance.now()}
    return
  }
  if(paused||gameOver)return;
  switch(e.key){
    case'ArrowLeft':e.preventDefault();movePiece(-1,0);break;
    case'ArrowRight':e.preventDefault();movePiece(1,0);break;
    case'ArrowDown':e.preventDefault();movePiece(0,1);break;
    case'ArrowUp':e.preventDefault();rotatePiece();break;
    case' ':e.preventDefault();hardDrop();break;
  }
});

// ─── 触摸按钮 ──────────────────────────
function bindBtn(id,fn){
  const btn=document.getElementById(id);
  btn.addEventListener('pointerdown',e=>{e.preventDefault();fn()});
  btn.addEventListener('touchstart',e=>{e.preventDefault();fn()});
}
bindBtn('btnLeft',()=>movePiece(-1,0));
bindBtn('btnRight',()=>movePiece(1,0));
bindBtn('btnDown',()=>movePiece(0,1));
bindBtn('btnRotate',()=>rotatePiece());
bindBtn('btnDrop',()=>hardDrop());

// ─── 滑动手势 ──────────────────────────
let touchStartX,touchStartY;
canvas.addEventListener('touchstart',e=>{
  e.preventDefault();
  touchStartX=e.touches[0].clientX;touchStartY=e.touches[0].clientY;
},{passive:false});
canvas.addEventListener('touchend',e=>{
  if(touchStartX==null)return;
  const t=e.changedTouches[0]||e.touches[0];
  if(!t)return;
  const dx=t.clientX-touchStartX,dy=t.clientY-touchStartY;
  const absDx=Math.abs(dx),absDy=Math.abs(dy);
  if(Math.max(absDx,absDy)<15)rotatePiece();
  else if(absDy>absDx*1.5&&dy>0)hardDrop();
  else if(absDx>absDy){if(dx>0)movePiece(1,0);else movePiece(-1,0)}
  touchStartX=null;
});

// ─── 重新开始 ──────────────────────────
document.getElementById('restartBtn').addEventListener('click',startGame);
document.getElementById('restartBtn').addEventListener('pointerdown',e=>{e.stopPropagation();startGame()});

function startGame(){
  initBoard();score=0;level=1;lines=0;gameOver=false;paused=false;
  dropInterval=800;current=null;next=null;
  document.getElementById('gameoverOverlay').classList.add('hidden');
  document.getElementById('pauseOverlay').classList.add('hidden');
  updateUI();spawnNext();draw();
  if(animId)cancelAnimationFrame(animId);
  lastDropTime=performance.now();
  animId=requestAnimationFrame(gameLoop);
}

startGame();
</script>
